import java.util.*;

class Solution {
  public int[] groupStrings(String[] words) {
    int n = words.length;
    DSU d = new DSU(n);
    Map<Integer, Integer> first = new HashMap<>();
    for (int i = 0; i < n; i++) {
      int mask = 0;
      for (char c : words[i].toCharArray()) mask |= 1 << (c - 'a');
      first.putIfAbsent(mask, i);
      d.union(i, first.get(mask));
      for (int b = 0; b < 26; b++)
        if ((mask & (1 << b)) != 0) d.union(i, first.getOrDefault(mask ^ (1 << b), i));
      for (int x = 0; x < 26; x++)
        if ((mask & (1 << x)) == 0)
          for (int y = 0; y < 26; y++)
            if ((mask & (1 << y)) != 0)
              d.union(i, first.getOrDefault(mask ^ (1 << y) | (1 << x), i));
    }
    int groups = 0, largest = 0;
    for (int i = 0; i < n; i++)
      if (d.find(i) == i) {
        groups++;
        largest = Math.max(largest, d.size[i]);
      }
    return new int[] {groups, largest};
  }

  static class DSU {
    int[] p, size;

    DSU(int n) {
      p = new int[n];
      size = new int[n];
      for (int i = 0; i < n; i++) {
        p[i] = i;
        size[i] = 1;
      }
    }

    int find(int x) {
      return p[x] == x ? x : (p[x] = find(p[x]));
    }

    void union(int a, int b) {
      if (a == b) return;
      a = find(a);
      b = find(b);
      if (a == b) return;
      if (size[a] < size[b]) {
        int t = a;
        a = b;
        b = t;
      }
      p[b] = a;
      size[a] += size[b];
    }
  }
}
